import numpy as np
def clusters(a, bg=None):
    bg_=bg if bg is not None else int(np.bincount(a.flat).argmax())
    m,n=a.shape; visited=np.zeros_like(a,bool); res=[]
    for p in np.argwhere(a!=bg_):
        if visited[p]: continue
        stack=[p]; comp={p}; visited[p]=True
        while stack:
            q=tuple(stack.pop())
            for nb in ((q[0]+1,q[1]),(q[0]-1,q[1]),(q[0],q[1]+1),(q[0],q[1]-1)):
                if 0<=nb[0]<m and 0<=nb[1]<n and a[nb]!=bg_ and not visited[nb]:
                    visited[nb]=True; comp.add(nb); stack.append(nb)
        if len(comp)<=1: continue
        norm=tuple(sorted((c[0]-min(c[0] for c in comp), c[1]-min(c[1] for c in comp)) for c in comp))
        res.append((comp,norm,len(norm)))
    return res
